result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/combobox/src/Combobox.tsx", "content": "import React, {
  useId,
  useRef,
  useState,
  type KeyboardEvent,
  type ChangeEvent,
} from "react";

export interface ComboboxOption {
  label: string;
  value: string;
}

export interface ComboboxProps {
  options: ComboboxOption[];
  onSelect?: (option: ComboboxOption) => void;
}

export function Combobox({ options, onSelect }: ComboboxProps) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(-1);

  const listboxId = useId();
  const optionId = (index: number) => `${listboxId}-option-${index}`;
  const inputRef = useRef<HTMLInputElement>(null);

  // Case-insensitive substring filter.
  const filtered = options.filter((option) =>
    option.label.toLowerCase().includes(query.toLowerCase()),
  );

  const openList = () => {
    setOpen(true);
    setActiveIndex(filtered.length > 0 ? 0 : -1);
  };

  const closeList = () => {
    setOpen(false);
    setActiveIndex(-1);
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    setQuery(event.target.value);
    // Reopening/filtering always shows the list; start at first match.
    setOpen(true);
    setActiveIndex(event.target.value ? 0 : -1);
  };

  const selectOption = (option: ComboboxOption) => {
    setQuery(option.label);
    onSelect?.(option);
    closeList();
    inputRef.current?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    switch (event.key) {
      case "ArrowDown":
        event.preventDefault(); // keep focus on the input (activedescendant pattern)
        if (!open) {
          openList();
        } else if (filtered.length > 0) {
          setActiveIndex((i) => (i + 1) % filtered.length);
        }
        break;
      case "ArrowUp":
        event.preventDefault(); // keep focus on the input
        if (!open) {
          openList();
          setActiveIndex(filtered.length - 1);
        } else if (filtered.length > 0) {
          setActiveIndex((i) => (i - 1 + filtered.length) % filtered.length);
        }
        break;
      case "Enter": {
        event.preventDefault();
        if (!open) break;
        const active = filtered[activeIndex];
        if (active) selectOption(active);
        break;
      }
      case "Escape":
        if (open) {
          event.preventDefault();
          closeList();
        }
        break;
    }
  };

  return (
    <>
      <input
        ref={inputRef}
        type="text"
        role="combobox"
        aria-expanded={open}
        aria-controls={listboxId}
        aria-activedescendant={
          open && activeIndex >= 0 ? optionId(activeIndex) : undefined
        }
        aria-autocomplete="list"
        value={query}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
      />
      {open && (
        <ul id={listboxId} role="listbox">
          {filtered.map((option, index) => (
            <li
              key={option.value}
              id={optionId(index)}
              role="option"
              aria-selected={index === activeIndex}
              onMouseDown={(event) => event.preventDefault()}
              onClick={() => selectOption(option)}
            >
              {option.label}
            </li>
          ))}
          {filtered.length === 0 && (
            <li role="status">No results</li>
          )}
        </ul>
      )}
    </>
  );
}

export default Combobox;
"})
