result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/combobox/src/Combobox.test.tsx", "content": "import { describe, it, expect, vi } from "vitest";
import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { Combobox, type ComboboxOption } from "./Combobox";

const FRUITS: ComboboxOption[] = [
  { label: "Apple", value: "apple" },
  { label: "Apricot", value: "apricot" },
  { label: "Banana", value: "banana" },
  { label: "Blueberry", value: "blueberry" },
  { label: "Cherry", value: "cherry" },
];

function setup(props: Partial<Parameters<typeof Combobox>[0]> = {}) {
  const onSelect = vi.fn();
  const utils = render(<Combobox options={FRUITS} onSelect={onSelect} {...props} />);
  const input = screen.getByRole("combobox") as HTMLInputElement;
  return { ...utils, input, onSelect };
}

function getOptionLabels(): string[] {
  const listbox = screen.getByRole("listbox");
  return within(listbox)
    .queryAllByRole("option")
    .map((el) => el.textContent);
}

describe("Combobox", () => {
  it("renders collapsed initially with aria-expanded=false and no listbox", () => {
    const { input } = setup();
    expect(input).toHaveAttribute("aria-expanded", "false");
    expect(input.getAttribute("aria-controls")).toBeTruthy();
    expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
    expect(input).not.toHaveAttribute("aria-activedescendant");
  });

  it("typing filters options case-insensitively into a listbox", async () => {
    const user = userEvent.setup();
    const { input } = setup();

    await user.type(input, "ap");

    expect(input).toHaveAttribute("aria-expanded", "true");
    const listbox = screen.getByRole("listbox");
    expect(listbox).toHaveAttribute("id", input.getAttribute("aria-controls"));
    expect(getOptionLabels()).toEqual(["Apple", "Apricot"]);

    await user.clear(input);
    await user.type(input, "BAN");
    expect(getOptionLabels()).toEqual(["Banana"]);
  });

  it("ArrowDown/ArrowUp move the active option without moving DOM focus (activedescendant)", async () => {
    const user = userEvent.setup();
    const { input } = setup();

    await user.click(input);
    // Clicking alone doesn't open in this implementation; open via arrow.
    await user.keyboard("{ArrowDown}");

    expect(input).toHaveAttribute("aria-expanded", "true");
    expect(input).toHaveFocus();
    expect(input).toHaveAttribute(
      "aria-activedescendant",
      `${input.getAttribute("aria-controls")}-option-0`,
    );

    await user.keyboard("{ArrowDown}");
    expect(input).toHaveAttribute(
      "aria-activedescendant",
      `${input.getAttribute("aria-controls")}-option-1`,
    );
    expect(input).toHaveFocus(); // focus never leaves the input

    await user.keyboard("{ArrowUp}{ArrowUp}");
    // Wraps from index 0 to the last option.
    expect(input).toHaveAttribute(
      "aria-activedescendant",
      `${input.getAttribute("aria-controls")}-option-4`,
    );
    expect(input).toHaveFocus();

    // No option element receives DOM focus.
    screen.getAllByRole("option").forEach((option) => {
      expect(option).not.toHaveFocus();
    });
  });

  it("Enter selects the active option object via onSelect", async () => {
    const user = userEvent.setup();
    const { input, onSelect } = setup();

    await user.type(input, "cher"); // opens, activeIndex = first match
    await user.keyboard("{ArrowDown}"); // wraps to same single match
    await user.keyboard("{Enter}");

    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect).toHaveBeenCalledWith({ label: "Cherry", value: "cherry" });
    expect(onSelect.mock.calls[0][0]).toBe(FRUITS[4]); // the actual option object
    expect(input).toHaveValue("Cherry");
  });

  it("Escape closes the list and restores collapsed state", async () => {
    const user = userEvent.setup();
    const { input } = setup();

    await user.type(input, "an");
    expect(screen.getByRole("listbox")).toBeInTheDocument();
    expect(input).toHaveAttribute("aria-expanded", "true");

    await user.type(input, "{Escape}");
    expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
    expect(input).toHaveAttribute("aria-expanded", "false");
    expect(input).not.toHaveAttribute("aria-activedescendant");
    expect(input).toHaveFocus();
  });

  it("shows a 'No results' item with role status when nothing matches", async () => {
    const user = userEvent.setup();
    setup();

    await user.type(screen.getByRole("combobox"), "zzz");

    const listbox = screen.getByRole("listbox");
    expect(within(listbox).queryAllByRole("option")).toHaveLength(0);
    expect(screen.getByRole("status")).toHaveTextContent("No results");
    // activedescendant is absent when there is no active option.
    expect(screen.getByRole("combobox")).not.toHaveAttribute(
      "aria-activedescendant",
    );
  });

  it("keeps aria-expanded truthful through an entire interaction cycle", async () => {
    const user = userEvent.setup();
    const { input } = setup();

    expect(input).toHaveAttribute("aria-expanded", "false");

    await user.type(input, "b");
    expect(input).toHaveAttribute("aria-expanded", "true");

    // Filtering down to no matches keeps the list open (with status message).
    await user.type(input, "zzz");
    expect(input).toHaveAttribute("aria-expanded", "true");
    expect(screen.getByRole("status")).toBeInTheDocument();

    // Backspace restores matches.
    await user.type(input, "{Backspace}");
    expect(getOptionLabels().length).toBeGreaterThan(0);

    await user.keyboard("{Escape}");
    expect(input).toHaveAttribute("aria-expanded", "false");

    // Reopen with ArrowDown.
    await user.keyboard("{ArrowDown}");
    expect(input).toHaveAttribute("aria-expanded", "true");
  });
});
"})
